SELECT "nct", "author", "year", "publication_type", "other_biomarker_inclusion", "cancer_type", "primary_endpoint"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Hepatocellular' AND "other_biomarker_inclusion" = 'No';

SELECT "nct", "author", "year", "publication_type", "trial_phase", "ici_class", "therapy_modality", "cancer_type", "ici_name", "treatment_regimen"
FROM public."clinical_trials"
WHERE "ici_class" = 'PD-L1' AND "cancer_type" = 'Colorectal' AND "trial_phase" = 'Phase 3' AND "therapy_modality" = 'Monotherapy';

SELECT "nct", "author", "year", "publication_type", "follow_up_type", "cancer_type", "follow_up_duration_rx_months", "follow_up_duration_control_months"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Colorectal' AND "follow_up_type" = 'Median';

SELECT "nct", "author", "year", "publication_type", "lines_of_treatment", "therapy_modality", "cancer_type", "combination_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Colorectal' AND NULLIF(regexp_replace(("lines_of_treatment")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2 AND "therapy_modality" = 'Combination';

SELECT "nct", "author", "year", "publication_type", "combination_type", "cancer_type", "treatment_regimen", "primary_endpoint"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Urothelial' AND "combination_type" = 'ICI+Chemo';

SELECT "nct", "author", "year", "publication_type", "pdl1_inclusion", "ici_class", "cancer_type", "ici_name", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Breast' AND "ici_class" = 'PD1' AND "pdl1_inclusion" = 'Yes';

SELECT "nct", "author", "year", "publication_type", "ici_class", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Renal cell' AND "ici_class" = 'PD1' AND NULLIF(regexp_replace(("year")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2018;

SELECT "nct", "author", "year", "publication_type", "ici_name", "therapy_modality", "cancer_type", "total_sample_size", "trial_phase"
FROM public."clinical_trials"
WHERE "ici_name" = 'Pembrolizumab' AND "cancer_type" = 'Renal cell' AND "therapy_modality" = 'Combination';

SELECT "nct", "author", "year", "publication_type", "ici_name", "trial_phase", "cancer_type", "trial_name", "treatment_regimen"
FROM public."clinical_trials"
WHERE "ici_name" = 'Durvalumab, Tremelimumab' AND "cancer_type" = 'Colorectal' AND "trial_phase" = 'Phase 2';

SELECT "nct", "author", "year", "publication_type", "ici_name", "follow_up_duration_overall_months", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Mesothelioma' AND "ici_name" = 'Nivolumab, Ipilimumab' AND NULLIF(regexp_replace(("follow_up_duration_overall_months")::text, '[^0-9\.-]', '', 'g'), '')::numeric > 21;

SELECT "nct", "author", "year", "publication_type", "ici_class", "cancer_type", "trial_phase"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Mesothelioma' AND "ici_class" = 'PD1' AND NULLIF(regexp_replace(("year")::text, '[^0-9\.-]', '', 'g'), '')::numeric >= 2018;

SELECT "nct", "author", "year", "publication_type", "other_biomarker_inclusion", "cancer_type", "primary_endpoint"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Head and Neck' AND "other_biomarker_inclusion" = 'Yes';

SELECT "nct", "author", "year", "publication_type", "ici_name", "trial_phase", "cancer_type"
FROM public."clinical_trials"
WHERE "ici_name" = 'Durvalumab, Tremelimumab' AND "cancer_type" = 'Small Cell Lung' AND "trial_phase" = 'Phase 3' AND "publication_type" = 'Follow-up';

SELECT "nct", "author", "year", "publication_type", "combination_type", "cancer_type", "treatment_regimen", "primary_endpoint"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Small Cell Lung' AND "combination_type" = 'ICI+ICI+Chemo';

SELECT "nct", "author", "year", "publication_type", "included_in_ma", "ici_class", "cancer_type", "ici_name"
FROM public."clinical_trials"
WHERE "cancer_type" = 'Small Cell Lung' AND "ici_class" = 'PD-L1, CTLA-4' AND "included_in_ma" = 'Yes';
